// Beacon signs the exact bytes it sends: X-Beacon-Signature = 'sha256=' + HMAC-SHA256(body).
// Verify against the raw body, before parsing it, and compare in constant time.
const crypto = require('crypto');

const SECRET = 'PASTE_THE_WEBHOOK_SECRET_HERE';

const headers = $input.first().json.headers ?? {};
const given = String(headers['x-beacon-signature'] ?? '');
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = 'sha256=' + crypto.createHmac('sha256', SECRET).update(raw).digest('hex');

const valid =
  given.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(given), Buffer.from(expected));
if (!valid) {
  return [{ json: { valid: false } }];
}

const payload = JSON.parse(raw.toString('utf8'));
return [{ json: { valid: true, event: payload.event, deliveryId: payload.deliveryId, ...payload.scan } }];
